15	template <typename keyType>
16	std::string GetAlgoString(const std::map<keyType, std::string>& levelMap, keyType key)
17	{
18	    auto iter = levelMap.find(key);
19	    if (iter == levelMap.end()) {
20	        return "invalid algo type";
21	    } else {
22	        return iter->second;
23	    }
24	}
25	
26	std::string AlgTypeToStr(const AlgType algType)
27	{
28	    AlgTypeLevel0 algTypeLevel0 = algType.algoLevel0;
29	    AlgTypeLevel1 algTypeLevel1 = algType.algoLevel1;
30	    AlgTypeLevel2 algTypeLevel2 = algType.algoLevel2;
31	    std::string algStrLevel0 = GetAlgoString(HCCL_ALGO_LEVEL0_NAME_MAP, algTypeLevel0);
32	    std::string algStrLevel1 = GetAlgoString(HCCL_ALGO_LEVEL1_NAME_MAP, algTypeLevel1);
33	    std::string algStrLevel2 = GetAlgoString(HCCL_ALGO_LEVEL2_NAME_MAP, algTypeLevel2);
34	    std::string algStr;
35	    algStr.append("level0:")
36	        .append(algStrLevel0)
37	        .append(",level1:")
38	        .append(algStrLevel1)
39	        .append(",level2:")
40	        .append(algStrLevel2);
41	    return algStr;
42	}
43	
44	std::string TransferAlgTypeStr(AlgType algType)
45	{
46	    std::string algTypeStr;
47	    auto level2Iter = HCCL_ALGO_LEVEL2_NAME_MAP.find(algType.algoLevel2);
48	    auto level0Iter = HCCL_ALGO_LEVEL0_NAME_MAP.find(algType.algoLevel0);
49	    auto level1Iter = HCCL_ALGO_LEVEL1_NAME_MAP.find(algType.algoLevel1);
50	    if (level0Iter == HCCL_ALGO_LEVEL0_NAME_MAP.end() || level1Iter == HCCL_ALGO_LEVEL1_NAME_MAP.end()
51	        || level2Iter == HCCL_ALGO_LEVEL2_NAME_MAP.end()) {
52	        algTypeStr = "not found";
53	    } else {
54	        // 将枚举值转换为整数进行拼接
55	        algTypeStr.append(std::to_string(static_cast<int>(algType.algoLevel0)))
56	            .append("-")
57	            .append(std::to_string(static_cast<int>(algType.algoLevel1)))
58	            .append("-")
59	            .append(std::to_string(static_cast<int>(algType.algoLevel2)));
60	    }
61	    return algTypeStr;
62	}
63	
64	std::string TransferAlgType(AlgType algType)
65	{
66	    std::string algTypeStr;
67	    auto level0Iter = HCCL_ALGO_LEVEL0_NAME_MAP.find(algType.algoLevel0);
68	    auto level1Iter = HCCL_ALGO_LEVEL1_NAME_MAP.find(algType.algoLevel1);
69	    auto level2Iter = HCCL_ALGO_LEVEL2_NAME_MAP.find(algType.algoLevel2);
70	    if (level0Iter == HCCL_ALGO_LEVEL0_NAME_MAP.end() || level1Iter == HCCL_ALGO_LEVEL1_NAME_MAP.end()
71	        || level2Iter == HCCL_ALGO_LEVEL2_NAME_MAP.end()) {
72	        algTypeStr = "not found";
73	    } else {
74	        // 将枚举值转换为整数进行拼接
75	        algTypeStr.append(static_cast<std::string>(level0Iter->second))
76	            .append("-")
77	            .append(static_cast<std::string>(level1Iter->second))
78	            .append("-")
79	            .append(static_cast<std::string>(level2Iter->second));
80	    }
81	    return algTypeStr;
82	}
