34	// 获取芯片类型
35	#ifdef __cplusplus
36	extern "C" {
37	#endif
38	HcclResult __HcclGetDeviceType(HcclDevType& devType)
39	{
40	    if (LIKELY((g_deviceType != HcclDevType::DEV_TYPE_COUNT))) {
41	        devType = g_deviceType;
42	        return HCCL_SUCCESS;
43	    }
44	
45	    std::string socName;
46	    CHK_RET(HcclGetSocVer(socName));
47	
48	    //  根据芯片版本号获取芯片类型
49	    HCCL_DEBUG("[HcclGetDeviceType]socName = %s.", socName.c_str());
50	    if (socName.find("Ascend950") != std::string::npos) {
51	        devType = HcclDevType::DEV_TYPE_950;
52	        g_deviceType = devType;
53	        HCCL_DEBUG("[HcclGetDeviceType]DeviceType = %d.", static_cast<s32>(g_deviceType));
54	        return HCCL_SUCCESS;
55	    }
56	
57	    if (socName.find("Ascend910_96") != std::string::npos || socName.find("Ascend960") != std::string::npos
58	        || socName.find("ascend960") != std::string::npos) {
59	        devType = HcclDevType::DEV_TYPE_960;
60	        g_deviceType = devType;
61	        HCCL_DEBUG("[HcclGetDeviceType]DeviceType = %d.", static_cast<s32>(g_deviceType));
62	        return HCCL_SUCCESS;
63	    }
64	
65	    auto iter = HCCL_SOC_VER_CONVERT.find(socName);
66	    if (iter == HCCL_SOC_VER_CONVERT.end()) {
67	        HCCL_ERROR(
68	            "[Get][DeviceType]errNo[0x%016llx] rtGetSocVersion get illegal chipver, chip_ver[%s].",
69	            HCCL_ERROR_CODE(HCCL_E_RUNTIME), socName.c_str());
70	        return HCCL_E_RUNTIME;
71	    }
72	    devType = iter->second;
73	    g_deviceType = devType;
74	    return HCCL_SUCCESS;
75	}
76	hccl_weak_alias(__HcclGetDeviceType, HcclGetDeviceType);
