30	std::string GetEnv(std::string IdName)
31	{
32	    constexpr size_t MAX_ENV_VALUE_SIZE = 1024;
33	    char envValue[MAX_ENV_VALUE_SIZE] = {0};
34	    char* mmSysGetEnvValue = envValue;
35	    mmSysGetEnvValue = std::getenv(IdName.c_str());
36	    if (mmSysGetEnvValue != nullptr && mmSysGetEnvValue[0] != '\0') {
37	        return std::string(mmSysGetEnvValue);
38	    } else {
39	        return "EmptyString";
40	    }
41	}
