145	        HCCL_WARNING(
146	            "[ParseMultipleDimensionSplitRatio] HCCL_ALG_MULTIPLE_DIMENSION_SPLIT_RATIO[%s] parse failed, use default.",
147	            multipleDimensionSplitRatioStr.c_str());
148	        g_algEnvConfig.multipleDimensionSplitRatioSet = false;
149	        g_algEnvConfig.multipleDimensionSplitRatio = 0;
150	        return HCCL_E_PARA;
