176	HcclResult InitEnvConfig()
177	{
178	    std::lock_guard<std::mutex> lock(g_algEnvConfigMutex);
179	    // 解析算子展开模式
180	    HcclResult ret = ParseOpExpansion();
181	    RPT_ENV_ERR(
182	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
183	        std::vector<std::string>({GetEnv("HCCL_OP_EXPANSION_MODE"), "HCCL_OP_EXPANSION_MODE", "should be \"AI_CPU\""}));
184	    CHK_PRT_RET(
185	        ret != HCCL_SUCCESS,
186	        HCCL_ERROR(
187	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse "
188	            "HCCL_OP_EXPANSION_MODE failed. errorno[%d]",
189	            HCCL_ERROR_CODE(ret), ret),
190	        ret);
191	
192	    if (g_algEnvConfig.initialized) {
193	        return HCCL_SUCCESS;
194	    }
195	
196	    // 解析hcclDeterministic,是否为确定性计算
197	    ret = ParseDeterministic();
198	    RPT_ENV_ERR(
199	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
200	        std::vector<std::string>(

200	        std::vector<std::string>(
201	            {GetEnv("HCCL_DETERMINISTIC"), "HCCL_DETERMINISTIC", "should be true ,false or strict"}));
202	    CHK_PRT_RET(
203	        ret != HCCL_SUCCESS,
204	        HCCL_ERROR(
205	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse "
206	            "HCCL_DETERMINISTIC failed. errorno[%d]",
207	            HCCL_ERROR_CODE(ret), ret),
208	        ret);
209	
210	    // 解析server内通信方式
211	    ret = ParseIntraLinkType();
212	    RPT_ENV_ERR(
213	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
214	        std::vector<std::string>(
215	            {"PCIE enable: " + std::string(GetEnv("HCCL_INTRA_PCIE_ENABLE"))
216	                 + " or ROCE enable: " + std::string(GetEnv("HCCL_INTRA_ROCE_ENABLE")),
217	             "HCCL_INTRA_PCIE_ENABLE or HCCL_INTRA_ROCE_ENABLE", "0 or 1 (but not both 1)"}));
218	    CHK_PRT_RET(
219	        ret != HCCL_SUCCESS,
220	        HCCL_ERROR(
221	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse intra "
222	            "comm type failed. errorno[%d]",
223	            HCCL_ERROR_CODE(ret), ret),
224	        ret);
225	
226	    // 解析Entry日志开关
227	    ret = ParseEntryLogEnable();
228	    RPT_ENV_ERR(
229	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
230	        std::vector<std::string>({GetEnv("HCCL_ENTRY_LOG_ENABLE"), "HCCL_ENTRY_LOG_ENABLE", "must be 0 or 1"}));
231	    CHK_PRT_RET(
232	        ret != HCCL_SUCCESS,
233	        HCCL_ERROR(
234	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse "
235	            "HCCL_ENTRY_LOG_ENABLE failed. errorno[%d]",
236	            HCCL_ERROR_CODE(ret), ret),
237	        ret);
238	
239	    // 解析超节点内节点间链路选择开关
240	    ret = ParseInterLinkType();
241	    RPT_ENV_ERR(
242	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
243	        std::vector<std::string>(
244	            {GetEnv("HCCL_INTER_HCCS_DISABLE"), "HCCL_INTER_HCCS_DISABLE", "should be true or false"}));
245	    CHK_PRT_RET(
246	        ret != HCCL_SUCCESS,
247	        HCCL_ERROR(
248	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse "
249	            "HCCL_INTER_HCCS_DISABLE failed. errorno[%d]",
250	            HCCL_ERROR_CODE(ret), ret),
251	        ret);
252	
253	    // 解析重执行设置
254	    ret = ParseRetryEnable();
255	    RPT_ENV_ERR(
256	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
257	        std::vector<std::string>({GetEnv("HCCL_OP_RETRY_ENABLE"), "HCCL_OP_RETRY_ENABLE", "should be 0 or 1"}));
258	    CHK_PRT_RET(
259	        ret != HCCL_SUCCESS,
260	        HCCL_ERROR(
261	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse HCCL_OP_RETRY_ENABLE failed. "
262	            "errorno[%d]",
263	            HCCL_ERROR_CODE(ret), ret),
264	        ret);
265	
266	    // 解析执行超时
267	    ret = ParseExecTimeout();
268	    RPT_ENV_ERR(
269	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
270	        std::vector<std::string>(
271	            {GetEnv("HCCL_EXEC_TIMEOUT"), "HCCL_EXEC_TIMEOUT", "a non-negative number with up to 2 decimals"}));
272	    CHK_PRT_RET(
273	        ret != HCCL_SUCCESS,
274	        HCCL_ERROR(
275	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse HCCL_EXEC_TIMEOUT failed. "
276	            "errorno[%d]",
277	            HCCL_ERROR_CODE(ret), ret),
278	        ret);
