281	    ret = ParseMultipleDimensionSplitRatio();
282	    const char* multipleDimensionSplitRatioEnv = std::getenv("HCCL_ALG_MULTIPLE_DIMENSION_SPLIT_RATIO");
283	    std::string multipleDimensionSplitRatioStr
284	        = (multipleDimensionSplitRatioEnv != nullptr) ? std::string(multipleDimensionSplitRatioEnv) : "EmptyString";
285	    RPT_ENV_ERR(
286	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
287	        std::vector<std::string>(
288	            {multipleDimensionSplitRatioStr, "HCCL_ALG_MULTIPLE_DIMENSION_SPLIT_RATIO", "a non-negative number"}));
289	    CHK_PRT_RET(
290	        ret != HCCL_SUCCESS,
291	        HCCL_ERROR(
292	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse "
293	            "HCCL_ALG_MULTIPLE_DIMENSION_SPLIT_RATIO failed. "
294	            "errorno[%d]",
295	            HCCL_ERROR_CODE(ret), ret),
296	        ret);
297	
298	    // 解析算法配置
299	    ret = ParseHcclAlgo();
300	    RPT_ENV_ERR(
301	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
302	        std::vector<std::string>(
303	            {GetEnv("HCCL_ALGO"), "HCCL_ALGO",
304	             "level0:NA;level1:<algo> or <op0>=level0:NA;level1:<algo0>/<op1>=level0:NA;level1:<algo1>"}));
305	    CHK_PRT_RET(
306	        ret != HCCL_SUCCESS,
307	        HCCL_ERROR(
308	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse "
309	            "hccl algorithm config failed. errorno[%d]",
310	            HCCL_ERROR_CODE(ret), ret),
311	        ret);
312	
313	    ret = InitDebugConfigByEnv();
314	    char* env = std::getenv("HCCL_DEBUG_CONFIG");
315	    std::string envValue = (env != nullptr) ? std::string(env) : "null";
316	    RPT_ENV_ERR(
317	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
318	        std::vector<std::string>({envValue, "HCCL_DEBUG_CONFIG", "ALG,TASK,RESOURCE(optionally prefixed with '^')"}));
319	    CHK_PRT_RET(
320	        ret != HCCL_SUCCESS,
321	        HCCL_ERROR(
322	            "[InitEnvParam]errNo[0x%016llx] In init environment param, parse "
323	            "HCCL_DEBUG_CONFIG failed. errorno[%d]",
324	            HCCL_ERROR_CODE(ret), ret),
325	        ret);
326	
327	    // 解析DfsConfig
328	    ret = ParseDfsConfig();
329	    char* dfsEnv = std::getenv("HCCL_DFS_CONFIG");
330	    std::string dfsEnvValue = (dfsEnv != nullptr) ? std::string(dfsEnv) : "null";
331	    RPT_ENV_ERR(
332	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
333	        std::vector<std::string>(
334	            {dfsEnvValue, "HCCL_DFS_CONFIG",
335	             "inconsistent_check:on or inconsistent_check:first or inconsistent_check:off"}));
336	    CHK_PRT_RET(
337	        ret != HCCL_SUCCESS,
338	        HCCL_ERROR(
339	            "[InitEnvParam]errNo[0x%016llx] In init environment param, parse "
340	            "HCCL_DFS_CONFIG failed. errorno[%d]",
341	            HCCL_ERROR_CODE(ret), ret),
342	        ret);
343	
344	    g_algEnvConfig.initialized = true;
345	
346	    return HCCL_SUCCESS;
347	}
348	
349	HcclResult ParseHcclAlgo()
350	{
351	    std::string hcclAlgo = GetEnv("HCCL_ALGO");
352	    if (hcclAlgo != "EmptyString") {
353	        CHK_RET(SetHcclAlgoConfig(hcclAlgo));
354	        HCCL_INFO("HCCL_ALGO set by environment to [%s]", hcclAlgo.c_str());
355	    } else {
356	        HCCL_INFO("HCCL_ALGO is not set");
357	    }
358	    return HCCL_SUCCESS;
359	}
360	
361	HcclResult SetHcclAlgoConfig(const std::string& hcclAlgo)
362	{
363	    std::string algoConfig = hcclAlgo;
364	    algoConfig.erase(std::remove(algoConfig.begin(), algoConfig.end(), ' '), algoConfig.end());
365	    if (algoConfig.empty()) {
366	        HCCL_INFO("hccl algo config is empty, HCCL use built-in algo selection.");
367	        return HCCL_SUCCESS;
368	    }
369	    std::vector<std::string> algoPerOptype;
370	    CHK_RET(SplitHcclOpType(algoConfig, algoPerOptype));
371	    bool anyCommonConfig = false;
372	    bool anySpecificConfig = false;
373	    CHK_RET(CheckAlgoConfigValid(algoPerOptype, anyCommonConfig, anySpecificConfig));
374	    if (anyCommonConfig) {
375	        CHK_RET(SetCommonAlgType(algoPerOptype));
376	    } else {
377	        CHK_RET(SetSpecificAlgType(algoPerOptype));
378	    }
379	    return HCCL_SUCCESS;
380	}
